const test=require('node:test'),assert=require('node:assert/strict'),D=require('./desk-model');
const source=(issue,id,run,task)=>({issue:{id:issue},asset:{id},key:id+'/'+run,request:{task}});
test('同一日志的解析批次聚合，原对象和历史引用不改写',()=>{const a=source('I1','L1','P1',null),b=source('I1','L1','P2','T2');const list=[a,b],before=JSON.stringify(list),g=D.groupSources(list);assert.equal(g.length,1);assert.equal(g[0].sources.length,2);assert.equal(g[0].latest,b);assert.equal(g[0].readable,b);assert.equal(D.chooseSource(list,a.key),a);assert.equal(JSON.stringify(list),before);});
test('最新重解析失败时保留此前可读批次，不把失败批次变成成功',()=>{const a=source('I1','L1','P1','T1'),b=source('I1','L1','P2',null),g=D.groupSources([a,b])[0];assert.equal(g.readable,a);assert.equal(g.latest,b);assert.equal(D.chooseSource([a,b],b.key),b);});
test('调查只能选当前工单来源，不沿用另一工单当前日志',()=>{const a=source('I1','L1','P1','T1'),b=source('I2','L2','P1','T2');assert.equal(D.chooseSource([a,b],a.key,'I2'),b);assert.equal(D.chooseSource([a],a.key,'I2'),null);assert.equal(D.groupSources([a,{...a,issue:{id:'I2'}}]).length,2);});
test('关键词、模块、级别和时间共同生效，零命中不回退全部日志',()=>{const rows=[{n:0,time:'2026-10-20T10:42:09+08:00',module:'Auth',level:'ERROR',content:'timeout A'},{n:1,time:'10:43:01.1',module:'Auth',level:'ERROR',content:'timeout B'}];assert.deepEqual(D.filterEvents(rows,{query:'timeout',level:'ERROR',module:'Auth',from:'10:42',to:'10:42'}).map(r=>r.n),[0]);assert.deepEqual(D.filterEvents(rows,{query:'absent'}),[]);});
test('时间分布保持所有事件和错误计数，同一时刻与未知时间安全处理',()=>{const rows=[{n:0,time:'10:42:00',level:'INFO'},{n:1,time:'10:42:00',level:'ERROR'},{n:2,time:'unknown',level:'INFO'}],bins=D.timeBins(rows);assert.equal(bins.flatMap(b=>b.rows).length,2);assert.equal(bins.reduce((n,b)=>n+b.errors,0),1);assert.deepEqual(D.timeBins([rows[2]]),[]);});
